const battleCoinReceipts = new WeakMap();
function creditBattleCoins(state) {
  if (!state || state.test || state.result !== 'win' || !S.hero || S.amb) return null;
  if (battleCoinReceipts.has(state)) return battleCoinReceipts.get(state);
  const encounter = B.ENCOUNTERS[state.encounter];
  if (!encounter || !Array.isArray(state.enemies)) return null;
  const killed = state.enemies.filter(function (enemy) { return enemy.hp <= 0; }).length;
  if (!killed) return null;
  const level = Math.max(1, Number(encounter.level) || 1);
  const receipt = { money: Math.max(1, Math.round(10 * (1 + 0.05 * (level - 1)) * killed)), saved: false };
  battleCoinReceipts.set(state, receipt);
  S.money += receipt.money;
  try { receipt.saved = save() === true; } catch (_) {}
  return receipt;
}
function battleCoinsHtml(receipt) {
  if (!receipt) return '';
  return '<section class="box" aria-label="Добыча за бой"><h3>Добыча</h3><p>Получено: ' + moneyHtml(receipt.money) + '</p>' + (receipt.saved ? '' : '<p role="alert">Деньги начислены, но сохранить игру не удалось. Не закрывайте вкладку до успешного сохранения.</p>') + '</section>';
}
function finish() {
  clearTimeout(timer);
  if (st.test) { finishTest(); return; }

const win = st.result === 'win';
